import{_ as e,o as l,c as r,a0 as t}from"./chunks/framework.n6XJP4w8.js";const u=JSON.parse('{"title":"使用与安装","description":"在安卓手机上把本站添加到主屏幕、离线阅读、搜索与字号调节说明。","frontmatter":{"title":"使用与安装","description":"在安卓手机上把本站添加到主屏幕、离线阅读、搜索与字号调节说明。"},"headers":[],"relativePath":"guide.md","filePath":"guide.md"}'),o={name:"guide.md"};function i(n,a,s,d,h,g){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="使用与安装" tabindex="-1">使用与安装 <a class="header-anchor" href="#使用与安装" aria-label="Permalink to &quot;使用与安装&quot;">​</a></h1><h2 id="添加到主屏幕-安卓-·-chrome-edge" tabindex="-1">添加到主屏幕（安卓 · Chrome / Edge） <a class="header-anchor" href="#添加到主屏幕-安卓-·-chrome-edge" aria-label="Permalink to &quot;添加到主屏幕（安卓 · Chrome / Edge）&quot;">​</a></h2><ol><li>用 <strong>Chrome</strong>（或 Edge、三星浏览器）打开本站地址（必须是 <strong>HTTPS</strong>，本地调试的 localhost 除外）。</li><li>点右上角 <strong>⋮</strong> 菜单 → <strong>添加到主屏幕</strong> / <strong>安装应用</strong>。</li><li>确认名称后点「添加」，桌面会出现图标；从图标打开即为全屏独立窗口。</li><li>首次打开后<strong>停留几秒</strong>，让 Service Worker 完成预缓存（约几 MB）。</li></ol><blockquote><p>若菜单里没有「安装」，请确认：地址是 HTTPS、没有使用无痕模式、且已刷新过一次页面。</p></blockquote><h2 id="站内阅读资料" tabindex="-1">站内阅读资料 <a class="header-anchor" href="#站内阅读资料" aria-label="Permalink to &quot;站内阅读资料&quot;">​</a></h2><ul><li>进入任一年份页 → 点「做题模式 / 复盘模式」文件名。</li><li>打开的是<strong>资料原件</strong>（独立 HTML），阅读器顶部有「← 返回」和「原始文件」。</li><li><strong>不需要语雀账号</strong>，本站已托管原件。</li><li>第一次打开需要联网（单个文件 0.8–8.3 MB）；打开后会自动进入缓存，断网再开同一份仍可读。</li><li>想提前离线：在年份页点「缓存本年资料（约 24 MB）」，等进度完成即可。</li></ul><h2 id="离线阅读" tabindex="-1">离线阅读 <a class="header-anchor" href="#离线阅读" aria-label="Permalink to &quot;离线阅读&quot;">​</a></h2><ul><li>预缓存范围：所有页面、脚本、样式、字体、图标、Pagefind 搜索索引。</li><li>安装后首次访问会把站点外壳写入缓存；之后<strong>断网</strong>打开，目录、年份页、使用说明与搜索结果均可正常使用。</li><li>资料原件（128 个 HTML，共约 393 MB）<strong>不在</strong>初始预缓存内，避免安装时占用过大空间： 读过的单份会自动缓存，也可在年份页整年下载。</li><li>想确认是否已缓存：断网后从桌面图标打开，能进入首页即成功。</li></ul><h2 id="全文搜索" tabindex="-1">全文搜索 <a class="header-anchor" href="#全文搜索" aria-label="Permalink to &quot;全文搜索&quot;">​</a></h2><ul><li>点顶部（手机为底部工具条）的「搜索」，或按键盘 <kbd>Ctrl</kbd> + <kbd>K</kbd>。</li><li>输入中文关键词，如「2010」「Text 3」「复盘」「长难句」。</li><li>搜索完全在本地进行，不上传任何内容。</li></ul><h2 id="阅读进度与字号" tabindex="-1">阅读进度与字号 <a class="header-anchor" href="#阅读进度与字号" aria-label="Permalink to &quot;阅读进度与字号&quot;">​</a></h2><ul><li>滚动阅读时顶部进度条会显示当前进度；离开页面时自动记住位置。</li><li>下次回到首页，点「继续上次阅读」即可跳回；进入该页时右下角也会出现续读提示。</li><li>顶部「A- / A+」调节正文字号，手机底部工具条同样可以调；设置只保存在本机浏览器。</li><li>深色模式：右上角图标切换（跟随系统或手动）。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：打开资料要登录语雀吗？</strong> A：不需要。128 份 HTML 原件已经下载并托管在本站，访问者直接点开即可。</p><p><strong>Q：为什么第一次打开资料要等？</strong> A：单个文件 0.8–8.3 MB，首次需要下载；下载后会进缓存，之后离线也能打开。年份页可整年缓存。</p><p><strong>Q：需要注册或登录本站吗？</strong> A：不需要。本站是纯静态站点，没有后端、没有账号体系，也不会上传任何数据。</p><p><strong>Q：换手机后进度还在吗？</strong> A：不在。所有偏好与进度都保存在当前浏览器的 localStorage 中，不跨设备同步，也不会离开你的手机。</p>',17)])])}const p=e(o,[["render",i]]);export{u as __pageData,p as default};
